// Extract Figma webhook payload
const webhookData = $input.first().json;

// Get data from webhook (handles both raw body and wrapped format)
const figmaUrl = webhookData.figmaUrl || webhookData.body?.figmaUrl;
const fileKey = webhookData.file_key || webhookData.body?.file_key;
const nodeId = webhookData.node_id || webhookData.body?.node_id;
const action = webhookData.action || webhookData.body?.action || 'generate_ui';

// Extract fileKey from URL if not provided
let finalFileKey = fileKey;
if (!finalFileKey && figmaUrl) {
  const urlMatch = figmaUrl.match(/figma\.com\/(?:file|design)\/([a-zA-Z0-9]+)/);
  if (urlMatch) {
    finalFileKey = urlMatch[1];
  }
}

// Extract nodeId from URL if not provided
let finalNodeId = nodeId;
if (!finalNodeId && figmaUrl) {
  const nodeMatch = figmaUrl.match(/node-id=([^&\s]+)/);
  if (nodeMatch) {
    finalNodeId = nodeMatch[1].replace(/-/g, ':');
  }
}

// Build message for agent
const message = `Generate Flutter code for this Figma design: ${figmaUrl}`;

const request = {
  action: action,
  figmaUrl: figmaUrl,
  fileKey: finalFileKey,
  nodeId: finalNodeId,
  message: message,
  context: {
    source: 'n8n_webhook',
    webhook_url: webhookData.webhookUrl,
    timestamp: new Date().toISOString()
  }
};

console.log('=== WEBHOOK RECEIVED ===');
console.log('Figma URL:', figmaUrl);
console.log('File Key:', finalFileKey);
console.log('Node ID:', finalNodeId);
console.log('========================');

return [{ json: request }];

// Handle agent response
const agentResponse = $input.first().json;

console.log('=== AGENT RESPONSE ===');
console.log(JSON.stringify(agentResponse, null, 2));
console.log('======================');

// Return response
return [{ json: agentResponse }];
